(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};

  // ① 建卍解项目
  const nameInput = document.querySelector('.tb-card .tb-input');
  if (!nameInput) return JSON.stringify({ error: '新建面板没打开' });
  setV(nameInput, '卍解测试·四件套');
  [...document.querySelectorAll('.tb-diff-opt')].find((b) => b.textContent.includes('卍解'))?.click();
  await sleep(300);
  [...document.querySelectorAll('.tb-btn-primary')].find((b) => b.textContent.includes('创建'))?.click();
  await sleep(3600);
  out.tabs = [...document.querySelectorAll('.pc-tab')].map((b) => b.textContent.trim());

  // ② 程序代码：贴一段 C（Keil 风格，带中文注释）
  [...document.querySelectorAll('.pc-btn')].find((b) => b.textContent.includes('直接贴代码'))?.click();
  await sleep(700);
  const inputs = [...document.querySelectorAll('.pc-input')];
  setV(inputs[0], 'main.c');
  setV(inputs[1], '主程序：LED 闪烁');
  setV(document.querySelector('.pc-textarea'), '#include "stm32f10x.h"\n\n// 主函数：让 PC13 上的 LED 闪起来\nint main(void) {\n  while (1) {\n    GPIO_SetBits(GPIOC, GPIO_Pin_13);\n  }\n}\n');
  await sleep(300);
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('放进作品'))?.click();
  await sleep(2200);
  out.codeGroups = [...document.querySelectorAll('.pc-group-title')].map((e) => e.textContent);
  out.codeItems = [...document.querySelectorAll('.pc-item-name')].map((e) => e.textContent);
  out.codeMeta = [...document.querySelectorAll('.pc-item-meta')].map((e) => e.textContent);
  out.codeShown = (document.querySelector('.pc-code')?.textContent || '').includes('GPIO_SetBits');
  return JSON.stringify(out);
})()

(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const out = {};
  const tab = (name) => [...document.querySelectorAll('.pc-tab')].find((b) => b.textContent.includes(name));

  // ③ 接线表
  tab('接线表')?.click();
  await sleep(700);
  const pinInputs = [...document.querySelectorAll('.pc-inline-form .pc-input')];
  out.pinInputs = pinInputs.length;
  setV(pinInputs[0], '超声波 HC-SR04');
  setV(pinInputs[1], 'TRIG');
  setV(pinInputs[2], 'D2');
  setV(pinInputs[3], '串 1k 电阻');
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('加一行'))?.click();
  await sleep(2000);
  out.pinRows = [...document.querySelectorAll('.pc-table tbody tr')].map((tr) => [...tr.querySelectorAll('input')].map((i) => i.value).join(' | '));

  // ④ 调试记录
  tab('调试记录')?.click();
  await sleep(700);
  setV(document.querySelector('.pc-input-full'), '串口一直是乱码');
  setV(document.querySelector('.pc-textarea-sm'), '波特率要和代码里一致，都是 9600；晶振频率也要在 Keil 里选对');
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.includes('记下来'))?.click();
  await sleep(1800);
  out.debugs = [...document.querySelectorAll('.pc-debug-problem')].map((e) => e.textContent);
  out.debugSolutions = [...document.querySelectorAll('.pc-debug-solution')].map((e) => e.textContent.slice(0, 20));

  // ⑤ 开发环境
  tab('开发环境')?.click();
  await sleep(700);
  setV(document.querySelector('.pc-textarea'), 'Keil µVision5（MDK-ARM）+ STM32F10x 器件包\nST-Link V2 下载器');
  [...document.querySelectorAll('.pc-btn-primary')].find((b) => b.textContent.trim() === '保存')?.click();
  await sleep(1800);
  out.envMsg = document.querySelector('.pc-msg')?.textContent || null;

  // ⑥ 存储层确认
  const projects = await s.listProjects();
  const p = projects.find((x) => x.name.includes('四件套'));
  const bundle = await s.getProject(p.id);
  out.stored = {
    difficulty: bundle.project.difficulty,
    codeNote: (bundle.project.codeNote || '').slice(0, 20),
    codeFiles: bundle.codeFiles.map((c) => ({ n: c.name, g: c.group, l: c.language })),
    pinRows: bundle.pinRows.map((r) => `${r.module}/${r.pin}→${r.boardPin}`),
    debugNotes: bundle.debugNotes.map((d) => d.problem),
  };
  out.projectId = p.id;
  return JSON.stringify(out);
})()
